class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        # Initialize variables as per node 2
        pow_bank = set()
        dp = [float('inf')] * (len(s) + 1)
        dp[len(s)] = 0
        i = 0

        # Decision node 3: Is s[i] == '0'?
        if s[i] == '0':
            # True branch: continue to next iteration (node 9)
            i += 1
            # Go back to decision node 3
            while i < len(s):
                if s[i] == '0':
                    i += 1
                    continue
                else:
                    break
            # Now process from the point where we have a non-zero character
            j = i
            while j < len(s):
                # Process substring s[i:j+1]
                dec = int(s[i:j+1], 2)
                # Check if dec is in pow_bank
                if dec in pow_bank:
                    # Update dp[i]
                    dp[i] = min(dp[i + 1] + 1, dp[i])
                    j += 1
                else:
                    j += 1
            # After processing all possible substrings starting at i
            # Move to decision node 7
            if dp[0] == float('inf'):
                return -1
            else:
                return dp[0]
        else:
            # False branch: loop through j from i to end of string (node 10)
            j = i
            while j < len(s):
                # Convert substring s[i:j+1] to decimal
                dec = int(s[i:j+1], 2)
                # Check if dec is in pow_bank
                if dec in pow_bank:
                    # Update dp[i]
                    dp[i] = min(dp[i + 1] + 1, dp[i])
                    j += 1
                else:
                    j += 1
            # After processing all possible substrings starting at i
            # Move to decision node 7
            if dp[0] == float('inf'):
                return -1
            else:
                return dp[0]
